<h1 class="h3 mb-4"><?= $routine ? 'Editar rotina' : 'Nova rotina' ?></h1><form method="post" action="/rotinas/salvar" class="card card-body bg-white"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8') ?>"><?php if ($routine): ?><input type="hidden" name="id" value="<?= (int) $routine['id'] ?>"><?php endif; ?><div class="row g-3"><div class="col-md-6"><label class="form-label">Nome</label><input class="form-control" name="nome" maxlength="120" required value="<?= htmlspecialchars($routine['nome'] ?? '', ENT_QUOTES, 'UTF-8') ?>"></div><div class="col-md-6"><label class="form-label">Canal</label><select class="form-select" name="canal_id" required><?php foreach ($channels as $channel): ?><option value="<?= (int) $channel['id'] ?>" <?= (($routine['canal_id'] ?? null) == $channel['id']) ? 'selected' : '' ?>><?= htmlspecialchars($channel['nome'] . ' (' . $channel['plataforma_nome'] . ')', ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Configuração de geração</label><select class="form-select" name="configuracao_id"><option value="">Sem configuração</option><?php foreach ($configs as $config): ?><option value="<?= (int) $config['id'] ?>" <?= (($routine['configuracao_id'] ?? null) == $config['id']) ? 'selected' : '' ?>><?= htmlspecialchars($config['nome'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Vídeos por dia</label><input class="form-control" type="number" min="1" max="50" name="videos_por_dia" value="<?= (int) ($routine['videos_por_dia'] ?? 1) ?>" required></div><div class="col-md-3"><label class="form-label">Horário local</label><input class="form-control" type="time" name="horario_local" value="<?= htmlspecialchars(substr($routine['horario_local'] ?? '12:00', 0, 5), ENT_QUOTES, 'UTF-8') ?>" required></div><div class="col-md-6"><label class="form-label">Fuso horário</label><input class="form-control" name="fuso_horario" value="<?= htmlspecialchars($routine['fuso_horario'] ?? 'America/Sao_Paulo', ENT_QUOTES, 'UTF-8') ?>" required></div><div class="col-12"><label><input type="checkbox" name="ativo" <?= (!$routine || $routine['ativo']) ? 'checked' : '' ?>> Ativa</label></div></div><div class="mt-4"><button class="btn btn-primary">Salvar</button> <a class="btn btn-outline-secondary" href="/rotinas">Cancelar</a></div></form>
